<?php
/** Normalized image generation result without image payload persistence. @package AIContentStudio */
if ( ! defined( 'ABSPATH' ) ) { exit; }

final class AICS_Image_Generation_Result {
	private bool $success; private string $provider; private string $model; private string $output_type; private string $mime_type; private int $width; private int $height; private string $safe_reference; private string $revised_prompt; private array $metadata; private string $error_code; private bool $retryable; private string $message; private int $http_status;
	private function __construct(array $data){foreach($data as $key=>$value){$this->{$key}=$value;}}
	public static function failure(string $code,string $message,string $provider='',bool $retryable=false,int $http_status=0,string $model=''):self{return new self(array('success'=>false,'provider'=>sanitize_key($provider),'model'=>self::text($model,100),'output_type'=>'','mime_type'=>'','width'=>0,'height'=>0,'safe_reference'=>'','revised_prompt'=>'','metadata'=>array(),'error_code'=>sanitize_key($code),'retryable'=>$retryable,'message'=>self::text($message,500),'http_status'=>max(0,min(599,$http_status))));}
	/** Structural success constructor for future adapters; rejects URLs and embedded image data. @return self|WP_Error */
	public static function success(array $data){$reference=self::text($data['safe_reference']??'',191);if(''===$reference||filter_var($reference,FILTER_VALIDATE_URL)||str_starts_with($reference,'data:')){return new WP_Error('unsafe_image_reference',__('The image result reference is invalid.','ai-content-studio'));}$mime=self::text($data['mime_type']??'',50);if(!in_array($mime,array('image/png','image/jpeg','image/webp'),true)){return new WP_Error('invalid_image_mime_type',__('The image result type is invalid.','ai-content-studio'));}return new self(array('success'=>true,'provider'=>sanitize_key((string)($data['provider']??'')),'model'=>self::text($data['model']??'',100),'output_type'=>sanitize_key((string)($data['output_type']??'')),'mime_type'=>$mime,'width'=>absint($data['width']??0),'height'=>absint($data['height']??0),'safe_reference'=>$reference,'revised_prompt'=>self::text($data['revised_prompt']??'',5000),'metadata'=>self::metadata($data['metadata']??array()),'error_code'=>'','retryable'=>false,'message'=>self::text($data['message']??'',500),'http_status'=>max(0,min(599,absint($data['http_status']??0)))));}
	public function is_success():bool{return $this->success;} public function get_error_code():string{return $this->error_code;} public function is_retryable():bool{return $this->retryable;} public function get_message():string{return $this->message;} public function get_provider():string{return $this->provider;} public function get_model():string{return $this->model;} public function get_http_status():int{return $this->http_status;} public function to_array():array{return get_object_vars($this);}
	private static function text($value,int $max):string{$value=is_scalar($value)?sanitize_text_field((string)$value):'';return function_exists('mb_substr')?mb_substr($value,0,$max,'UTF-8'):substr($value,0,$max);}
	private static function metadata($value):array{if(!is_array($value)){return array();}$out=array();foreach(array('request_id','created_at') as $key){if(isset($value[$key])&&is_scalar($value[$key])){$out[$key]=self::text($value[$key],191);}}return $out;}
}
